problems.answerCode:
def solution(numbers):
    answer = 0
    for n in numbers:
        if n % 2 == 0:
            answer += n
    return answer


print(solution([1, 2, 3, 4]))
print(solution([5, 7]))
print(solution([10, 20, 31]))

